fn replace_chars(str1: &Vec<char>, old_char: char, new_char: char) -> Vec<char> {
    // Pre-allocate a new vector with the same length as the input.
    let mut result = Vec::with_capacity(str1.len());

    // Scan through each character and push the replacement or the original.
    for &c in str1.iter() {
        if c == old_char {
            result.push(new_char);
        } else {
            result.push(c);
        }
    }

    result
}

fn main() {
    let input = vec!['a', 'b', 'a', 'c', 'a'];
    let output = replace_chars(&input, 'a', 'z');
    assert_eq!(output, vec!['z', 'b', 'z', 'c', 'z']);
    println!("Replaced vector: {:?}", output);
}